-- 1. Loot: 612 rows on 24 heroic Deadmines / Shadowfang Keep creatures point at reference tables 50022-50049, which exist
--    neither here nor in LoA. They never dropped anything.
DELETE FROM `creature_loot_template` WHERE `mincountOrRef` IN (-50022,-50023,-50024,-50025,-50026,-50027,-50028,-50029,-50030,-50031,-50032,-50033,-50034,-50035,-50036,-50037,-50038,-50039,-50040,-50041,-50042,-50043,-50044,-50045,-50046,-50047,-50048,-50049);
