DELETE FROM `gameobject_loot_template` WHERE `entry` IN (42520,42522,42524,42525,42528,42825,42826,42931,43122,43126,43236,202776,202777,202781,207734,208311,213362,218372,218373);
-- Reference 102269: 36 items at 8.3% each in one group is 299%; equal chance instead
UPDATE `reference_loot_template` SET `ChanceOrQuestChance` = 0 WHERE `entry` = 102269 AND `groupid` = 1 AND `ChanceOrQuestChance` > 0 AND `mincountOrRef` > 0;
UPDATE `creature_template` SET `lootid` = 0 WHERE `lootid` = 69570 AND NOT EXISTS (SELECT 1 FROM `creature_loot_template` WHERE `entry` = 69570); -- loot id with no loot (LoA: a currency drop only)
