-- 6. Dungeon Finder: the pre-5.0 Scarlet Monastery and Scholomance bosses were still marked as the last encounter of the
--    dungeons that replaced them, so the new last bosses (Flameweaver Koegler, Whitemane, Gandling) were skipped
UPDATE `instance_encounters` SET `lastEncounterDungeon` = 0 WHERE `entry` IN (448,450,463) AND `lastEncounterDungeon` IN (163,164,2);

-- 7. Scripts
DELETE FROM `spell_script_names` WHERE `spell_id` = 61698 AND `ScriptName` = 'spell_gen_ds_flush_knockback'; -- that spell does not exist
-- 333 escort points for 12 creatures that have no C++ script (two now run on SmartAI); only C++ escorts read this table
DELETE FROM `script_waypoint` WHERE `entry` IN (349,467,1754,3849,3850,4962,5391,6182,6575,7780,8856,17238) AND NOT EXISTS (SELECT 1 FROM `creature_template` WHERE `creature_template`.`entry` = `script_waypoint`.`entry` AND `ScriptName` <> '');
-- SmartAI paths 38707 / 38709 (Northwatch Gryphon) are numbered from 0; the core starts at 1 and skipped the first point
SET @d26 := (SELECT COUNT(*) FROM `waypoints` WHERE `entry` = 38707 AND `pointid` = 0);
UPDATE `waypoints` SET `pointid` = `pointid` + 1 WHERE `entry` = 38707 AND @d26 > 0 ORDER BY `pointid` DESC;
UPDATE `smart_scripts` SET `event_param1` = `event_param1` + 1 WHERE `entryorguid` = 38707 AND `source_type` = 0 AND `event_type` = 40 AND `event_param2` = 38707 AND @d26 > 0;
SET @d26 := (SELECT COUNT(*) FROM `waypoints` WHERE `entry` = 38709 AND `pointid` = 0);
UPDATE `waypoints` SET `pointid` = `pointid` + 1 WHERE `entry` = 38709 AND @d26 > 0 ORDER BY `pointid` DESC;
UPDATE `smart_scripts` SET `event_param1` = `event_param1` + 1 WHERE `entryorguid` = 38709 AND `source_type` = 0 AND `event_type` = 40 AND `event_param2` = 38709 AND @d26 > 0;
